using System;
using System.IO;
using Avalonia.Controls;
using Avalonia.Platform;
using Hymnal.Core.Tests.Infrastructure;
using Xunit;

namespace Hymnal.Core.Tests.Views;

/// <summary>The app icon (generated by tools/IconGen/IconGen.cs) is embedded and loads as the windows use it.</summary>
[Collection("AvaloniaUi")]
public sealed class AppIconTests
{
    static AppIconTests() => ReactiveUiTestBootstrap.EnsureInitialized();

    [Fact]
    public void Icon_assets_load_as_window_icon_and_bitmap()
    {
        ReactiveUiTestBootstrap.RunOnUiThread(() =>
        {
            using (var ico = AssetLoader.Open(new Uri("avares://Hymnal/Assets/hymnal.ico")))
                Assert.NotNull(new WindowIcon(ico));

            // The headless platform decodes every bitmap as 1×1, so read the size from the PNG header instead.
            using var png = AssetLoader.Open(new Uri("avares://Hymnal/Assets/hymnal-256.png"));
            var header = new byte[24];
            png.ReadExactly(header);
            Assert.Equal("PNG", System.Text.Encoding.ASCII.GetString(header, 1, 3));
            Assert.Equal(256, System.Buffers.Binary.BinaryPrimitives.ReadInt32BigEndian(header.AsSpan(16, 4)));
        });
    }

    [Fact]
    public void Windows_and_executable_use_the_hymnal_icon()
    {
        Assert.Contains("Icon=\"/Assets/hymnal.ico\"", Read("src/Hymnal/Views/MainWindow.axaml"));
        Assert.Contains("Icon=\"/Assets/hymnal.ico\"", Read("src/Hymnal/Views/AboutDialog.axaml"));
        Assert.Contains(@"<ApplicationIcon>Assets\hymnal.ico</ApplicationIcon>", Read("src/Hymnal/Hymnal.csproj"));
        Assert.DoesNotContain("avalonia-logo", Read("src/Hymnal/Views/MainWindow.axaml"));
    }

    private static string Read(string relativePath)
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir != null)
        {
            var candidate = Path.Combine(dir.FullName, relativePath);
            if (File.Exists(candidate))
                return File.ReadAllText(candidate);
            dir = dir.Parent;
        }

        throw new FileNotFoundException($"Could not locate repository file '{relativePath}'.");
    }
}
